"""Section-level ACS source reviews; no completeness inferred from sequence tables."""
import json
import ledger as L
from review_batch_0001 import evidence
# DOI suffix, inspected PDF pages, supported notes, outstanding source checks, optional family ID
NOTES=[
('acs.jpclett.5b02238','pp1–8; FigS1/S2, absorption methods and Table1','SI shows modified origami irradiation and a single-biotin stability control. TT(CTC)3TT and TT(ATA)3TT are the assayed oligomers; SI does not establish complete template routing or staple mapping.','Read main construction methods and map assay oligos/biotin attachment to original template; do not count irradiated conditions as new cores.',None),
('acs.langmuir.5b02569','pp1–2; TableS1 and reference1','28 of170 nanotube staples receive5-prime capture extensions (AAT)8T4, arranged for14 Au nanoparticles. TableS1 gives helix/column identities and explicitly defers full170 core sequences to Bui2010 Programmable Periodicity of Quantum Dot Arrays with DNA Origami Nanotubes.','Verify source-image sequences and exact28 replacements against parent170-staple set; establish lattice and original template identity.','RDE0018'),
('acs.analchem.5b02524','pp1–4; orientation derivation and final experimental-parameter paragraph','SI models triangle orientation and uses measured polarizability and6HB conductivity from main paper. No design or sequence table in this4-page SI; main design-specific methods remain needed.','Inspect main Methods for actual6HB and triangle provenance; extracted mathematical glyphs are corrupted and not reliable numerical evidence.',None),
('acsnano.5b06894','pp4–5 FigS1/S2; p20 TablesS2/S3; pp21,26–27 TablesS4–S6','Poly(APPV-DNA) follows straight, left-turned and right-turned tracks on origami. SI separates nonextended staples, M/L/R extended tracks, fluorophore-tagged replacements, and guiding/removing strands LgDNA/LrDNA/RgDNA/RrDNA. Polymer conformation and origami core are distinct.','Map shared staples and track replacements, color-coded sequence domains and label variants against routing; TableS4 continuation pp22–25 remains to inspect.','RDE0019'),
('acsnano.5b05865','pp1–3; footnote defining designsA/B and TableS2','Simulation designA has24 scaffold domains of16 bases and twelve32nt staples binding two domains. Related time-calibration designB uses48nt staples binding three domains. SI lists simulated strand sequences forA; reported assembly simulation is not evidence of experimental synthesis.','Inspect main topology and distinguish designB calibration from designA; independently verify sequence strings and full routing, not just384nt arithmetic.','RDE0020'),
('acsnano.5b05972','pp1–3; contents and FigS1 caption','Supplement explicitly follows tall-rectangle folding by AFM. Temperature-dependent folding intermediates are observations of a rectangle, not automatically distinct authored designs. Separate ZIP/XLS assets are already downloaded but not yet inspected in this review.','Inspect construction/parent design, remainder of SI and ZIP/XLS members; identify staple stoichiometry interventions without treating image intermediates as new cores.',None),
('acsnano.5b05309','pp16–20; SF1–3 and references; pp51,54,60–61 sequence-section headings and linker/blocker definitions','Four monomer types differ in sequence breaks, hairpin positions and interface staples. Linkers contain30–32bp scaffold-binding,8bp internal pairing,4T and5nt sticky end; blockers have30–32bp binding and4T. Deletions maintain10.43bp/turn. Structural, label, anchor, linker and blocker sets are listed separately; tetramer is an assembly.','Verify complete per-monomer set composition and compare parent rectangle/dimerization sources; do not flatten assembly connectors into a single monomer core.','RDE0021'),
('jacs.5b11566','pp1–5; experimental assembly and FigS1–3 captions','M13mp18 clamp assembles with inside capture strands for Au nanorod binding and three outside capture groups defining recognition sites. AuNP placement produces different cargo assemblies on the clamp; these are not automatically different core geometries.','Inspect routing/sequence pages and enumerate capture replacements, clamp core and AuNP cargo variants separately.','RDE0022'),
('jacs.5b10502','pp3–4,39,41–43; Notes1,5–7 and FigS1/S31/S33','T1/T2 use a32-helix tall rectangle with7008 scaffold bases and10.44bp/turn; distinguish hairpin sets and linker staples, withT2 rotated180degrees. Separate lattice tilesa/b change hairpins/linking. SI identifies5bp,6bp and6bp-floppy linker sets, blockers and common/hairpin body sets in downloaded workbook.','Read workbook sheets and validate exact combinations; separate monomer variants, dimers and lattice assemblies. Source has differing plus/minus20percent versus15percent design-strength descriptions; retain discrepancy.','RDE0023')]

NOTES += [
('acs.nanolett.6b00381','pp1–12; assembly/staple-set recipes, routing description and control comparison S3','SI names flat/tetrahedral/octahedral/dodecahedral trusses with CA/ABF/ABFD and design-specific staple subsets. Those truss objects fall outside narrow catalog scope. Crucially p7 also reports a conventional6HB control folded with p7308,p8064,M13mp18; whole-paper exclusion would discard this reuse.','Inspect native archive and6HB parent/source identity; separately record truss-object exclusion and control eligibility after figure review.',None),
('acs.nanolett.6b00530','pp9,11,18,20,24,27–28; construction, labeling and staple-list sections','M13mp18 nanostructure has14 internal handles functionalized with oligo bioconjugates. Cavity staples expose polyA15 handles; separate loop site binds Alexa647 label. Center/right-edge/left-edge/cavity staple categories are listed; terminalTT prevents aggregation. Cargo photolysis is distinct from core folding.','PDF extraction emits image syntax errors; inspect source diagrams visually and verify all sequence categories and cargo variants.','RDE0024'),
('acsnano.5b07671','pp1–5 entire SI; FigS3–7 and TableS1','SI FigS3 identifies triangular origami; subsequent experiments compare BMEPC-loaded origami and free photosensitizer. These are loading conditions, not evidence for new routing. No staple list appears in the5-page supplement.','Inspect main Methods and parent triangle source; preserve chemical loading versus core topology distinction.',None),
('jacs.5b13107','pp1–3,5; ring preparation and anti-handle protein/lipid conjugation','p8064 ring is folded with staple strands; separate anti-handle i couples Cys-VAMP2 with Alexa647 and anti-handle ii couples lipid with Alexa488. Protein/lipid tethers and ring staples have distinct roles.','Inspect remaining ring routing/handle stoichiometry and sequence sections; reconcile earlier ring/lipid-template sources.','RDE0025'),
('acsnano.6b01339','pp1–4; Methods8-mer synthesis and FigS1/S2','RectanglesA/B share routing/staple layout but have distinct sequences. FourLxy linker sets and complementary quencher strands support staged dimers,tetramers,octamers; elongated ribbons can also form. EtBr changes conformation. Rectangle monomers and shaft constructs are folded from M13mp18; assemblies are not single authored cores.','Review shaft design, chemical-adduct variants, sequence sections and parent templates; keep polymerization strands separate from ordinary staple extensions.','RDE0026'),
('jacs.6b00958','pp1–2,4–7; material preparation, monomer design and FigS1–3','p7560 curved24HB monomer has two curvature versions from layer-specific insertions/deletions. LH/RH AuNP capture mixtures replace corresponding noncapture sets over a common core. Head-head and tail-tail connectors form dimers/rings;12 of24 helices carry3-base overhangs with complementary scaffold sites on the others.','Inspect CAD schemesS20–22 and sequence sets; map both curvature versions and LH/RH capture alternatives separately from ring assembly.','RDE0027')]

def main():
 acs={r['doi']:r for r in json.loads((L.ROOT/'acs_acquisition.json').read_text())['records']}
 for suffix,pages,note,question,did in NOTES:
  doi='10.1021/'+suffix;f=next(f for f in acs[doi]['files'] if f['name'].endswith('.pdf'))
  ev=evidence(L.ROOT/'assets'/f['local_file'],f['url'],'PDF '+pages)
  p=next(p for p in L.read('publication_reviews') if p['registry_key']==doi)
  contributions=['uncertain'] if suffix in ['acs.analchem.5b02524','acsnano.5b05972'] else ['new_design'] if suffix=='acsnano.5b05865' else ['modified_design','reused_design'] if suffix=='acs.langmuir.5b02569' else ['uncertain']
  p.update(review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=contributions,catalog_eligibility='unresolved',access='partial',evidence=p['evidence']+[ev] if ev not in p['evidence'] else p['evidence'],rationale=note,unresolved_questions=list(dict.fromkeys(p['unresolved_questions']+[question,'Complete design source set and catalog eligibility remain unverified; inspect main article and remaining relevant source sections.'])),reviewer='Codex inspected primary SI sections',run_id='B0008',date=L.DATE)
  L.upsert('publication_reviews',p,'Record bounded ACS supplement review with explicit source gaps')
  if did:
   old=next((d for d in L.read('design_evidence') if d['design_id']==did),None);assert old is None or old['publication_keys']==[doi]
   L.upsert('design_evidence',dict(design_id=did,publication_keys=[doi],named_objects=[p['legacy_record']['publication']],core_variant_composition=note,lattice_decision='unresolved',catalog_eligibility='unresolved',source_completeness='not_verified',source_files=[ev],evidence=[ev],outstanding_checks=p['unresolved_questions'],relationships=[],variant_links=[],legacy_record={},review_run='B0008',date=L.DATE),'Retain provisional family-level extraction without asserting unique core or complete sources')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0008');a='Reviewed15 ACS supplements at named sections; preserved core/functionalization/assembly distinctions and10 provisional family records. Truss paper includes a6HB control; no paper-wide exclusion.'
 if a not in b['completed_actions']:b['completed_actions'].append(a)
 b.update(after_counts=L.counts(),validation=[L.validate()],next_queue=['Finish8 remaining low/broad records; all15 ACS supplements have a first section-level review.','Review8 remaining low/broad records and acquisition alternatives.','Inspect downloaded fold-pathway ZIP/XLS and dimerization workbook; verify parent/core/variant mapping.']);L.upsert('batches',b,'Checkpoint9 substantive SI reviews; source completion remains open');print(L.validate())
if __name__=='__main__':main()
